        typeName = "小说";
    } else if (type === 2) {
        typeName = "套图";
    } else {
        typeName = "漫画"; // 明确处理类型3
    }  
    java.toast("\n✅ 已切换到: 【" + typeName + "】");
}

function showSearchType() {
    var currentType = initSearchType();
    var typeName;   
    if (currentType === 1) {
        typeName = "小说";
    } else if (currentType === 2) {
        typeName = "套图";
    } else {
        typeName = "漫画"; // 明确处理类型3
    }   
    java.longToast("\n🔍 当前搜索类型: 【" + typeName + "】");
}
initSearchType();

